-- =====================================================
-- PROJECT 4: PRODUCT ANALYTICS
-- TASK 1: REVENUE BY PRODUCT
-- Business Question:
-- Which products generate the most revenue?
-- =====================================================

SELECT
    p.product_id,
    p.product_name,

    -- Calculate total revenue generated by the product
    SUM(
        oi.quantity
        * oi.unit_price
        * (1 - oi.discount_percent / 100)
    ) AS total_revenue,

    -- Count total units sold
    SUM(oi.quantity) AS units_sold

FROM products AS p

JOIN order_items AS oi
    ON p.product_id = oi.product_id

GROUP BY
    p.product_id,
    p.product_name

ORDER BY total_revenue DESC

LIMIT 10;


-- =====================================================
-- PROJECT 4: PRODUCT ANALYTICS
-- TASK 2: UNITS SOLD BY PRODUCT
-- Business Question:
-- Which products sell the highest number of units?
-- =====================================================

SELECT
    p.product_id,
    p.product_name,

    -- Calculate total quantity sold for each product
    SUM(oi.quantity) AS units_sold,

    -- Calculate the revenue generated by those units
    SUM(
        oi.quantity
        * oi.unit_price
        * (1 - oi.discount_percent / 100)
    ) AS total_revenue

FROM products AS p

JOIN order_items AS oi
    ON p.product_id = oi.product_id

GROUP BY
    p.product_id,
    p.product_name

ORDER BY units_sold DESC

LIMIT 10;


-- =====================================================
-- PROJECT 4: PRODUCT ANALYTICS
-- TASK 3: PROFIT BY PRODUCT
-- Business Question:
-- Which products generate the most gross profit?
-- =====================================================

SELECT
    p.product_id,
    p.product_name,

    -- Calculate total gross profit
    SUM(
        (
            oi.unit_price
            * (1 - oi.discount_percent / 100)
            - p.cost_price
        )
        * oi.quantity
    ) AS total_profit,

    -- Calculate total revenue for comparison
    SUM(
        oi.quantity
        * oi.unit_price
        * (1 - oi.discount_percent / 100)
    ) AS total_revenue

FROM products AS p

JOIN order_items AS oi
    ON p.product_id = oi.product_id

GROUP BY
    p.product_id,
    p.product_name

ORDER BY total_profit DESC

LIMIT 10;



-- =====================================================
-- PROJECT 4: PRODUCT ANALYTICS
-- TASK 4: PROFIT MARGIN BY PRODUCT
-- Business Question:
-- Which products have the highest gross profit margin?
-- =====================================================

SELECT
    p.product_id,
    p.product_name,

    -- Calculate total revenue
    SUM(
        oi.quantity
        * oi.unit_price
        * (1 - oi.discount_percent / 100)
    ) AS total_revenue,

    -- Calculate total gross profit
    SUM(
        (
            oi.unit_price
            * (1 - oi.discount_percent / 100)
            - p.cost_price
        )
        * oi.quantity
    ) AS total_profit,

    -- Calculate gross profit margin percentage
    SUM(
        (
            oi.unit_price
            * (1 - oi.discount_percent / 100)
            - p.cost_price
        )
        * oi.quantity
    )
    /
    SUM(
        oi.quantity
        * oi.unit_price
        * (1 - oi.discount_percent / 100)
    )
    * 100 AS profit_margin_percent

FROM products AS p

JOIN order_items AS oi
    ON p.product_id = oi.product_id

GROUP BY
    p.product_id,
    p.product_name

ORDER BY profit_margin_percent DESC

LIMIT 10;


-- =====================================================
-- PROJECT 4: PRODUCT ANALYTICS
-- TASK 5: AVERAGE SELLING PRICE BY PRODUCT
-- Business Question:
-- What is the average selling price of each product?
-- =====================================================

SELECT
    p.product_id,
    p.product_name,

    -- Calculate the average listed selling price
    AVG(oi.unit_price) AS average_selling_price,

    -- Show total units sold for context
    SUM(oi.quantity) AS units_sold

FROM products AS p

JOIN order_items AS oi
    ON p.product_id = oi.product_id

GROUP BY
    p.product_id,
    p.product_name

ORDER BY average_selling_price DESC

LIMIT 10;


-- =====================================================
-- PROJECT 4: PRODUCT ANALYTICS
-- TASK 6: DISCOUNT BY PRODUCT
-- Business Question:
-- Which products receive the largest total discounts?
-- =====================================================

SELECT
    p.product_id,
    p.product_name,

    -- Calculate total discount amount given to customers
    SUM(
        oi.quantity
        * oi.unit_price
        * (oi.discount_percent / 100)
    ) AS total_discount_amount,

    -- Calculate revenue after discount
    SUM(
        oi.quantity
        * oi.unit_price
        * (1 - oi.discount_percent / 100)
    ) AS total_revenue

FROM products AS p

JOIN order_items AS oi
    ON p.product_id = oi.product_id

GROUP BY
    p.product_id,
    p.product_name

ORDER BY total_discount_amount DESC

LIMIT 10;


-- =====================================================
-- PROJECT 4: PRODUCT ANALYTICS
-- TASK 7: REVENUE BY CATEGORY
-- Business Question:
-- Which product categories generate the most revenue?
-- =====================================================

SELECT
    c.category_id,
    c.category_name,

    -- Calculate total revenue generated by the category
    SUM(
        oi.quantity
        * oi.unit_price
        * (1 - oi.discount_percent / 100)
    ) AS total_revenue,

    -- Calculate total units sold in the category
    SUM(oi.quantity) AS units_sold

FROM categories AS c

JOIN products AS p
    ON c.category_id = p.category_id

JOIN order_items AS oi
    ON p.product_id = oi.product_id

GROUP BY
    c.category_id,
    c.category_name

ORDER BY total_revenue DESC;


-- =====================================================
-- PROJECT 4: PRODUCT ANALYTICS
-- TASK 8: UNITS SOLD BY CATEGORY
-- Business Question:
-- Which product categories sell the highest number of units?
-- =====================================================

SELECT
    c.category_id,
    c.category_name,

    -- Calculate total units sold in each category
    SUM(oi.quantity) AS units_sold,

    -- Calculate revenue generated by those units
    SUM(
        oi.quantity
        * oi.unit_price
        * (1 - oi.discount_percent / 100)
    ) AS total_revenue

FROM categories AS c

JOIN products AS p
    ON c.category_id = p.category_id

JOIN order_items AS oi
    ON p.product_id = oi.product_id

GROUP BY
    c.category_id,
    c.category_name

ORDER BY units_sold DESC;



-- =====================================================
-- PROJECT 4: PRODUCT ANALYTICS
-- TASK 9: PROFIT BY CATEGORY
-- Business Question:
-- Which product categories generate the most gross profit?
-- =====================================================

SELECT
    c.category_id,
    c.category_name,

    -- Calculate total gross profit
    SUM(
        (
            oi.unit_price
            * (1 - oi.discount_percent / 100)
            - p.cost_price
        )
        * oi.quantity
    ) AS total_profit,

    -- Calculate total revenue for comparison
    SUM(
        oi.quantity
        * oi.unit_price
        * (1 - oi.discount_percent / 100)
    ) AS total_revenue

FROM categories AS c

JOIN products AS p
    ON c.category_id = p.category_id

JOIN order_items AS oi
    ON p.product_id = oi.product_id

GROUP BY
    c.category_id,
    c.category_name

ORDER BY total_profit DESC;


-- =====================================================
-- PROJECT 4: PRODUCT ANALYTICS
-- TASK 10: CATEGORY PROFIT MARGIN
-- Business Question:
-- Which categories have the highest gross profit margin?
-- =====================================================

SELECT
    c.category_id,
    c.category_name,

    -- Calculate total revenue
    SUM(
        oi.quantity
        * oi.unit_price
        * (1 - oi.discount_percent / 100)
    ) AS total_revenue,

    -- Calculate total gross profit
    SUM(
        (
            oi.unit_price
            * (1 - oi.discount_percent / 100)
            - p.cost_price
        )
        * oi.quantity
    ) AS total_profit,

    -- Calculate gross profit margin percentage
    SUM(
        (
            oi.unit_price
            * (1 - oi.discount_percent / 100)
            - p.cost_price
        )
        * oi.quantity
    )
    /
    SUM(
        oi.quantity
        * oi.unit_price
        * (1 - oi.discount_percent / 100)
    )
    * 100 AS profit_margin_percent

FROM categories AS c

JOIN products AS p
    ON c.category_id = p.category_id

JOIN order_items AS oi
    ON p.product_id = oi.product_id

GROUP BY
    c.category_id,
    c.category_name

ORDER BY profit_margin_percent DESC;


-- =====================================================
-- PROJECT 4: PRODUCT ANALYTICS
-- TASK 11: PRODUCT SALES BY CHANNEL
-- Business Question:
-- Which products perform best across sales channels?
-- =====================================================

SELECT
    p.product_id,
    p.product_name,
    o.channel,

    -- Calculate revenue generated by the product
    -- within each sales channel
    SUM(
        oi.quantity
        * oi.unit_price
        * (1 - oi.discount_percent / 100)
    ) AS total_revenue,

    -- Calculate units sold within each channel
    SUM(oi.quantity) AS units_sold

FROM products AS p

JOIN order_items AS oi
    ON p.product_id = oi.product_id

JOIN orders AS o
    ON oi.order_id = o.order_id

GROUP BY
    p.product_id,
    p.product_name,
    o.channel

ORDER BY total_revenue DESC

LIMIT 20;


-- =====================================================
-- PROJECT 4: PRODUCT ANALYTICS
-- TASK 12: PRODUCT SALES BY REGION
-- Business Question:
-- Which products perform best across regions?
-- =====================================================

SELECT
    p.product_id,
    p.product_name,
    s.region,

    -- Calculate revenue generated by the product
    -- within each region
    SUM(
        oi.quantity
        * oi.unit_price
        * (1 - oi.discount_percent / 100)
    ) AS total_revenue,

    -- Calculate units sold within each region
    SUM(oi.quantity) AS units_sold

FROM products AS p

JOIN order_items AS oi
    ON p.product_id = oi.product_id

JOIN orders AS o
    ON oi.order_id = o.order_id

JOIN stores AS s
    ON o.store_id = s.store_id

GROUP BY
    p.product_id,
    p.product_name,
    s.region

ORDER BY total_revenue DESC

LIMIT 20;


-- =====================================================
-- PROJECT 4: PRODUCT ANALYTICS
-- TASK 13: BEST & WORST PRODUCTS
-- Business Question:
-- Which products perform strongly across revenue,
-- profit, margin, and sales volume?
-- =====================================================

SELECT
    p.product_id,
    p.product_name,

    -- Total units sold
    SUM(oi.quantity) AS units_sold,

    -- Total revenue after discounts
    SUM(
        oi.quantity
        * oi.unit_price
        * (1 - oi.discount_percent / 100)
    ) AS total_revenue,

    -- Total gross profit
    SUM(
        (
            oi.unit_price
            * (1 - oi.discount_percent / 100)
            - p.cost_price
        )
        * oi.quantity
    ) AS total_profit,

    -- Gross profit margin
    SUM(
        (
            oi.unit_price
            * (1 - oi.discount_percent / 100)
            - p.cost_price
        )
        * oi.quantity
    )
    /
    SUM(
        oi.quantity
        * oi.unit_price
        * (1 - oi.discount_percent / 100)
    )
    * 100 AS profit_margin_percent

FROM products AS p

JOIN order_items AS oi
    ON p.product_id = oi.product_id

GROUP BY
    p.product_id,
    p.product_name

ORDER BY total_profit DESC

LIMIT 20;

    
    
-- =====================================================
-- PROJECT 3: CUSTOMER ANALYTICS
-- TASK 14: HIGH-VALUE CUSTOMER IDENTIFICATION
-- Business Question:
-- Which customers are both high-value and frequent buyers?
-- =====================================================

SELECT
    c.customer_id,
    CONCAT(c.first_name, ' ', c.last_name) AS customer_name,

    -- Total revenue generated by the customer
    SUM(
        oi.quantity
        * oi.unit_price
        * (1 - oi.discount_percent / 100)
    ) AS lifetime_revenue,

    -- Number of orders placed by the customer
    COUNT(DISTINCT o.order_id) AS order_count

FROM customers AS c

JOIN orders AS o
    ON c.customer_id = o.customer_id

JOIN order_items AS oi
    ON o.order_id = oi.order_id

GROUP BY
    c.customer_id,
    c.first_name,
    c.last_name

-- High-value = ₹10 lakh+ revenue
-- Frequent = 5 or more orders
HAVING
    SUM(
        oi.quantity
        * oi.unit_price
        * (1 - oi.discount_percent / 100)
    ) > 1000000

    AND COUNT(DISTINCT o.order_id) >= 5

ORDER BY
    lifetime_revenue DESC;
    
    
    -- =====================================================
-- PROJECT 3: CUSTOMER ANALYTICS
-- TASK 15: CUSTOMER SEGMENTATION
-- Business Question:
-- How can customers be divided into meaningful
-- segments based on revenue and order frequency?
-- =====================================================

SELECT
    customer_id,
    customer_name,
    lifetime_revenue,
    order_count,

    -- Classify customers based on lifetime revenue
    -- and number of orders
    CASE
        WHEN lifetime_revenue >= 1500000
             AND order_count >= 8
            THEN 'VIP'

        WHEN lifetime_revenue >= 1000000
             AND order_count >= 5
            THEN 'Loyal'

        WHEN lifetime_revenue >= 500000
             AND order_count >= 3
            THEN 'Regular'

        ELSE 'One-Time / Low Value'
    END AS customer_segment

FROM (
    -- Calculate customer-level purchasing metrics
    SELECT
        c.customer_id,

        CONCAT(
            c.first_name,
            ' ',
            c.last_name
        ) AS customer_name,

        -- Total revenue generated by the customer
        SUM(
            oi.quantity
            * oi.unit_price
            * (1 - oi.discount_percent / 100)
        ) AS lifetime_revenue,

        -- Number of unique orders placed
        COUNT(DISTINCT o.order_id) AS order_count

    FROM customers AS c

    JOIN orders AS o
        ON c.customer_id = o.customer_id

    JOIN order_items AS oi
        ON o.order_id = oi.order_id

    GROUP BY
        c.customer_id,
        c.first_name,
        c.last_name
) AS customer_metrics

ORDER BY
    CASE customer_segment
        WHEN 'VIP' THEN 1
        WHEN 'Loyal' THEN 2
        WHEN 'Regular' THEN 3
        ELSE 4
    END,
    lifetime_revenue DESC;